// Extract and analyze eligibility benefits
const eligibilityData = items[0].json;
const fhirResource = eligibilityData.fhir_resource;

// Analyze coverage benefits
let benefits_analysis = {
  coverage_active: fhirResource?.status === 'active',
  has_deductible: false,
  has_copay: false,
  has_coinsurance: false,
  network_coverage: 'unknown'
};

// Process insurance benefits if available
if (fhirResource?.insurance && fhirResource.insurance[0]?.item) {
  const items = fhirResource.insurance[0].item;

  items.forEach(item => {
    const category = item.category?.text?.toLowerCase() || '';

    if (category.includes('deductible')) {
      benefits_analysis.has_deductible = true;
      benefits_analysis.deductible_amount = item.benefit?.[0]?.usedMoney?.value || 'Not specified';
    }

    if (category.includes('copay')) {
      benefits_analysis.has_copay = true;
      benefits_analysis.copay_amount = item.benefit?.[0]?.allowedMoney?.value || 'Not specified';
    }

    if (category.includes('coinsurance')) {
      benefits_analysis.has_coinsurance = true;
      benefits_analysis.coinsurance_rate = item.benefit?.[0]?.allowedMoney?.value || 'Not specified';
    }
  });
}

return [{
  json: {
    eligibility_analysis: benefits_analysis,
    mapping_quality: {
      auto_detected_fields: eligibilityData.mapping_summary?.auto_detected || 0,
      total_fields: eligibilityData.mapping_summary?.total_input_fields || 0,
      confidence_level: eligibilityData.mapping_summary?.high_confidence || 0,
      validation_status: eligibilityData.validation_summary?.status
    },
    fhir_resource_summary: {
      resource_type: fhirResource?.resourceType,
      resource_id: fhirResource?.id,
      status: fhirResource?.status,
      patient_reference: fhirResource?.patient?.reference,
      has_insurance: !!(fhirResource?.insurance && fhirResource.insurance.length > 0)
    },
    recommendations: [
      benefits_analysis.coverage_active ? "Coverage is active and valid" : "Check coverage status",
      benefits_analysis.has_deductible ? "Deductible information available" : "Consider adding deductible details",
      benefits_analysis.has_copay ? "Copay amounts specified" : "Copay information may be needed",
      "Resource ready for eligibility verification workflows"
    ]
  }
}];
